interface Function {}
interface Array<T> { length: number; [n: number]: T }
interface IterableIterator<T> { next(): { value: T; done?: boolean } }
interface ReadonlyMap<K, V> { get(key: K): V | undefined; readonly size: number }
interface Map<K, V> { get(key: K): V | undefined; set(key: K, value: V): this; entries(): IterableIterator<[K, V]>; readonly size: number }
interface MapConstructor { new <K, V>(): Map<K, V>; readonly prototype: Map<any, any> }
declare var Map: MapConstructor;
interface WeakMap<K extends object, V> { get(key: K): V | undefined }
interface ReadonlySet<T> { has(value: T): boolean; readonly size: number }
interface Set<T> { has(value: T): boolean; add(value: T): this; readonly size: number }
interface SetConstructor { new <T>(): Set<T>; readonly prototype: Set<any> }
declare var Set: SetConstructor;
interface WeakSet<T extends object> { has(value: T): boolean }
interface ObjectConstructor {
  keys(o: object): string[];
  values<T>(o: { [s: string]: T } | ArrayLike<T>): T[];
  values(o: {}): any[];
  entries<T>(o: { [s: string]: T } | ArrayLike<T>): [string, T][];
  entries(o: {}): [string, any][];
}
interface ArrayLike<T> { readonly length: number; readonly [n: number]: T }
declare var Object: ObjectConstructor;
type Record<K extends keyof any, T> = { [P in K]: T };
